1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  SECRET_PROVIDERS,
5	  type SecretProvider,
6	  createSecretSchema,
7	  rotateSecretSchema,
8	  updateSecretSchema,
9	} from "@paperclipai/shared";
10	import { forbidden } from "../errors.js";
11	import { validate } from "../middleware/validate.js";
12	import { assertBoard, assertCompanyAccess } from "./authz.js";
13	import { logActivity, secretService } from "../services/index.js";
14	import { expressHandler } from "../http/express-adapter.js";
15	import type { Handler, RequestCtx } from "../http/types.js";
16	import type { StorageService } from "../storage/types.js";
17	
18	export function secretRoutes(db: Db) {
19	  const router = Router();
20	  const svc = secretService(db);
21	  const configuredDefaultProvider = process.env.PAPERCLIP_SECRETS_PROVIDER;
22	  const defaultProvider = (
23	    configuredDefaultProvider && SECRET_PROVIDERS.includes(configuredDefaultProvider as SecretProvider)
24	      ? configuredDefaultProvider
25	      : "local_encrypted"
26	  ) as SecretProvider;
27	
28	  // Storage is not needed by any secret handler.
29	  const storageSentinel = new Proxy({} as StorageService, {
30	    get(_target, prop) {
31	      throw new Error(`secret handler unexpectedly accessed storage.${String(prop)}`);
32	    },
33	  });
34	
35	  // ---------------------------------------------------------------------------
36	  // Internal authz helpers operating on RequestCtx
37	  // ---------------------------------------------------------------------------
38	
39	  function assertBoardCtx(ctx: RequestCtx) {
40	    if (!ctx.actor || ctx.actor.type !== "board") {
41	      throw forbidden("Board access required");
42	    }
43	  }
44	
45	  // ---------------------------------------------------------------------------
46	  // Handlers
47	  // ---------------------------------------------------------------------------
48	
49	  const listSecretProviders: Handler = async (ctx) => {
50	    assertBoardCtx(ctx);
51	    const companyId = ctx.param("companyId");
52	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
53	    return Response.json(svc.listProviders());
54	  };
55	
56	  const listSecrets: Handler = async (ctx) => {
57	    assertBoardCtx(ctx);
58	    const companyId = ctx.param("companyId");
59	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
60	    const secrets = await svc.list(companyId);
61	    return Response.json(secrets);
62	  };
63	
64	  const createSecret: Handler = async (ctx) => {
65	    assertBoardCtx(ctx);
66	    const companyId = ctx.param("companyId");
67	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
68	    const body = await ctx.json<Record<string, unknown>>();
69	    const actor = ctx.actor!;
70	
71	    const created = await svc.create(
72	      companyId,
73	      {
74	        name: body.name as string,
75	        provider: (body.provider as SecretProvider | undefined) ?? defaultProvider,
76	        value: body.value as string,
77	        description: body.description as string | undefined,
78	        externalRef: body.externalRef as string | undefined,
79	      },
80	      { userId: actor.userId ?? "board", agentId: null },
81	    );
82	
83	    await logActivity(db, {
84	      companyId,
85	      actorType: "user",
86	      actorId: actor.userId ?? "board",
87	      action: "secret.created",
88	      entityType: "secret",
89	      entityId: created.id,
90	      details: { name: created.name, provider: created.provider },
91	    });
92	
93	    return Response.json(created, { status: 201 });
94	  };
95	
96	  const rotateSecret: Handler = async (ctx) => {
97	    assertBoardCtx(ctx);
98	    const id = ctx.param("id");
99	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
100	    const existing = await svc.getById(id);
101	    if (!existing) {
102	      return Response.json({ error: "Secret not found" }, { status: 404 });
103	    }
104	    const actor = ctx.actor!;
105	    const body = await ctx.json<Record<string, unknown>>();
106	
107	    const rotated = await svc.rotate(
108	      id,
109	      {
110	        value: body.value as string | undefined,
111	        externalRef: body.externalRef as string | undefined,
112	      },
113	      { userId: actor.userId ?? "board", agentId: null },
114	    );
115	
116	    await logActivity(db, {
117	      companyId: rotated.companyId,
118	      actorType: "user",
119	      actorId: actor.userId ?? "board",
120	      action: "secret.rotated",
121	      entityType: "secret",
122	      entityId: rotated.id,
123	      details: { version: rotated.latestVersion },
124	    });
125	
126	    return Response.json(rotated);
127	  };
128	
129	  const updateSecret: Handler = async (ctx) => {
130	    assertBoardCtx(ctx);
131	    const id = ctx.param("id");
132	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
133	    const existing = await svc.getById(id);
134	    if (!existing) {
135	      return Response.json({ error: "Secret not found" }, { status: 404 });
136	    }
137	    const actor = ctx.actor!;
138	    const body = await ctx.json<Record<string, unknown>>();
139	
140	    const updated = await svc.update(id, {
141	      name: body.name as string | undefined,
142	      description: body.description as string | undefined,
143	      externalRef: body.externalRef as string | undefined,
144	    });
145	
146	    if (!updated) {
147	      return Response.json({ error: "Secret not found" }, { status: 404 });
148	    }
149	
150	    await logActivity(db, {
151	      companyId: updated.companyId,
152	      actorType: "user",
153	      actorId: actor.userId ?? "board",
154	      action: "secret.updated",
155	      entityType: "secret",
156	      entityId: updated.id,
157	      details: { name: updated.name },
158	    });
159	
160	    return Response.json(updated);
161	  };
162	
163	  const deleteSecret: Handler = async (ctx) => {
164	    assertBoardCtx(ctx);
165	    const id = ctx.param("id");
166	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
167	    const existing = await svc.getById(id);
168	    if (!existing) {
169	      return Response.json({ error: "Secret not found" }, { status: 404 });
170	    }
171	    const actor = ctx.actor!;
172	
173	    const removed = await svc.remove(id);
174	    if (!removed) {
175	      return Response.json({ error: "Secret not found" }, { status: 404 });
176	    }
177	
178	    await logActivity(db, {
179	      companyId: removed.companyId,
180	      actorType: "user",
181	      actorId: actor.userId ?? "board",
182	      action: "secret.deleted",
183	      entityType: "secret",
184	      entityId: removed.id,
185	      details: { name: removed.name },
186	    });
187	
188	    return Response.json({ ok: true });
189	  };
190	
191	  // ---------------------------------------------------------------------------
192	  // Wire handlers via expressHandler
193	  // ---------------------------------------------------------------------------
194	
195	  const adapterDeps = { db, storage: storageSentinel };
196	
197	  router.get("/companies/:companyId/secret-providers", expressHandler(listSecretProviders, adapterDeps));
198	  router.get("/companies/:companyId/secrets", expressHandler(listSecrets, adapterDeps));
199	  router.post("/companies/:companyId/secrets", validate(createSecretSchema), expressHandler(createSecret, adapterDeps));
200	  router.post("/secrets/:id/rotate", validate(rotateSecretSchema), expressHandler(rotateSecret, adapterDeps));
201	  router.patch("/secrets/:id", validate(updateSecretSchema), expressHandler(updateSecret, adapterDeps));
202	  router.delete("/secrets/:id", expressHandler(deleteSecret, adapterDeps));
203	
204	  return router;
205	}
